      /* --- 聊天气泡核心修复 --- */

      /* 1. 气泡外层容器 */
      .bubble {
        display: flex;
        align-items: flex-start; /* 改为 flex-start 让头像始终对齐顶部（或者是 flex-end 对齐底部，看你喜好） */
        align-items: flex-end; /* 还是保持底部对齐比较像微信 */
        gap: 15px;

        /* 这里控制气泡整体的最大宽度，避免太长 */
        max-width: 85%;
        margin-bottom: 20px; /* 增加一点气泡间的距离 */
      }

      /* 2. 头像样式 */
      .bubble-avatar {
        width: 80px;
        height: 80px;
        border-radius: 50%;
        border: 2px solid #ff6b88;
        background: #fff;
        overflow: hidden;

        /* 【核心修复】禁止头像被压缩 */
        flex-shrink: 0;
      }

      /* 3. 头像里的图片 */
      .bubble-avatar img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center 25%;
        transform: scale(1.1);
      }

      /* 4. 气泡内容框 */
      .bubble-content {
        background: white;
        padding: 18px 25px; /* 内边距调整舒适一点 */
        border-radius: 25px;
        font-size: 24px;
        color: #333;
        box-shadow: 0 4px 10px rgba(0, 0, 0, 0.05);
        line-height: 1.5; /* 增加行高，多行文字更好看 */

        /* 【核心修复】强制长文本换行，防止撑开宽度 */
        word-break: break-word;
        white-space: pre-wrap; /* 保留换行符并允许自动换行 */

        /* 配合父级 max-width，这里不需要定死宽度，它会自动适应 */
        min-width: 0; /* Flex 布局下的文字溢出保护 */
      }

      /* 右侧（发送方）样式保持不变，但要确保继承上面的修复 */
      .bubble.sent {
        align-self: flex-end;
        flex-direction: row-reverse;
