/**
 * 将消息压入缓存，而不是直接发送
 * @param {string} text 消息内容
 */
function queueTavernMessage(text) {
    if (!text) return;
    tavernMessageBuffer.push(text);
    updateSyncButtonUI();
}

/**
 * 更新同步按钮的状态
 */
function updateSyncButtonUI() {
    const btn = document.getElementById("global-sync-btn");
    const badge = document.getElementById("sync-count-badge");

    if (tavernMessageBuffer.length > 0) {
        btn.style.display = "flex";
        badge.innerText = tavernMessageBuffer.length;
    } else {
        btn.style.display = "none";
    }
}

/**
 * 核心：一次性冲刷所有缓存消息并同步给 AI
 */
 async function flushTavernBuffer() {
    if (tavernMessageBuffer.length === 0) return;

    // 1. 开启 Loading
    const loader = document.getElementById("devLoading");
    if (loader) {
        loader.style.display = "flex";
        document.querySelector("#devLoading .loading-text").innerText = "正在同步店长决策...";
    }

    // --- 【核心修改：格式化消息】 ---
    // 根据当前挂件选中的模式确定抬头
    let modeTag = "【" + (currentNarrativeMode === 'novel' ? "小说" : "对话") + "模式】";

    // 构建最终文本：抬头 + 总表头 + 每一个决策内容（决策之间用换行隔开，不再加数字序号）
    const combinedAction = modeTag + "【店长决策汇总】：\n\n" + tavernMessageBuffer.join("\n\n");

    try {
        if (window.TavernHelper && window.TavernHelper.createChatMessages) {
            await window.TavernHelper.createChatMessages(
                [{ role: 'user', message: combinedAction }],
                { refresh: 'affected' }
            );
            if (window.TavernHelper.triggerSlash) {
                await window.TavernHelper.triggerSlash('/trigger');
            }
        }

        // 2. 清空缓存
        tavernMessageBuffer = [];
        updateSyncButtonUI();

        // 3. 进入场景处理器
        setTimeout(async () => {
            await processSceneQueue();
        }, 1000);

    } catch (e) {
        console.error("同步失败:", e);
        if (loader) loader.style.display = "none";
        alert("同步过程中出现错误。");
    }
}
