      function renderFinancialStatement() {
        const d = shopFinancials; 

        // --- 新增：根据 records 实时计算累计值 ---
        let calculatedIncome = 0;
        let calculatedExpense = 0;

        d.records.forEach(rec => {
          if (rec.type === 'income') {
            calculatedIncome += Math.abs(rec.amount);
          } else {
            calculatedExpense += Math.abs(rec.amount);
          }
        });

        // 1. 填充头部时间
        document.getElementById("receipt-date").innerText = "Update: " + d.lastUpdate;

        // 2. 填充余额和计算出来的累计统计
        document.getElementById("bill-balance").innerText = d.currentBalance;
        document.getElementById("bill-total-inc").innerText = "+ ¥" + calculatedIncome;
        document.getElementById("bill-total-exp").innerText = "- ¥" + calculatedExpense;
        document.getElementById("bill-grand-total").innerText = "¥" + d.currentBalance;

        // 3. 渲染列表记录
        const listContainer = document.getElementById("receipt-records-list");
        listContainer.innerHTML = "";

        d.records.forEach((rec) => {
          const isPlus = rec.type === "income";
          const row = document.createElement("div");
          row.className = "receipt-row";
          row.innerHTML = `
            <span class="row-date">${rec.date}</span>
            <span class="row-desc">${rec.item}</span>
            <span class="row-dots"></span>
            <span class="row-amt ${isPlus ? "amt-plus" : "amt-minus"}">
                ${isPlus ? "+" : ""}${rec.amount}
            </span>
          `;
          listContainer.appendChild(row);
        });
      }
