      function unlockNewIngredient(data) {
        // 如果已经解锁了，就不处理
        if (unlockedIngredients[data.id]) return;

        const baseItem = ingredientsDB.find(
          (i) => i.name === data.baseImageName,
        );

        const newItem = {
          id: data.id,
          name: data.name,
          type: data.type || (baseItem ? baseItem.type : "base"),
          z: data.z || (baseItem ? baseItem.z : 10),
          cost: data.cost || 5,
          season: data.season || "全",
          baseImageName: data.baseImageName,
          defaultTint: data.defaultTint,
          coreTags: data.coreTags || { n: "特调", l: 2 },
          subTags: data.subTags || null,
          desc: data.desc || "神秘的新解锁风味！",
        };

        // --- 修改点：直接通过 ID 存入对象 ---
        unlockedIngredients[data.id] = newItem;

        initDevInterface();
      }
