      function nextDialog() {
    // 1. 如果剧情已经决策完（进入了同步等待状态），不再响应点击
    if (isStoryFinished) return;

    // --- 【核心修复逻辑】 ---
    // 检查当前这一步是不是选择题
    if (dialogIndex >= 0 && dialogIndex < dialogData.length) {
        const currentData = dialogData[dialogIndex];
        const choiceOverlay = document.getElementById("choiceOverlay");

        // 如果当前步是 choices，且选择框现在是隐藏的（说明玩家刚才点过取消）
        // 则重新弹出当前的选择框，不再让索引增加
        if (currentData.type === "choices" && choiceOverlay.style.display === "none") {
            renderDynamicChoices(currentData);
            return; // 拦截，不执行后面的 dialogIndex++
        }
    }

    // --- 【原有的推进逻辑】 ---
    dialogIndex++;

    // 如果已经播到最后一句了，不再加索引
    if (dialogIndex >= dialogData.length) {
        dialogIndex = dialogData.length - 1; // 锁定在最后一步
        return;
    }

    const data = dialogData[dialogIndex];

    // 如果遇到了 JSON 中的选择分支
    if (data.type === "choices") {
        renderDynamicChoices(data); // 调用动态渲染函数
    } else {
        syncStoryUI(data); // 正常显示对话或执行动作
    }
}

