// 统一的物品/奶茶弹出函数
function showItemPopup(name, imgSrc, variantData, customTitle) {
    const overlay = document.getElementById("itemOverlay");
    const nameEl = document.getElementById("popupItemName");
    const imgContainer = document.querySelector(".item-img-container");
    const titleEl = document.querySelector(".item-title");

    if (!overlay || !imgContainer) return;

    // 1. 设置标题
    titleEl.innerText = customTitle || "获得新物品";

    // 2. 彻底清空容器（包括旧的 img 标签和残留的画布），只保留背景光芒
    imgContainer.innerHTML = '<div class="item-glow"></div>';

    // 3. 核心判断：这到底是一杯“成品奶茶”还是一件“普通原料/物品”
    const drinkData = shopMenu[name]; // 检查是否在配方库中

    if (drinkData) {
        // --- 情况 A: 这是一个已研发的成品奶茶 ---
        titleEl.innerText = "获得新饮品";
        nameEl.innerHTML = `<span style="color:#8b4513">【${drinkData.name}】</span>`;

        // 创建一个画布层
        const drinkCanvas = document.createElement("div");
        drinkCanvas.style.cssText = "width:600px; height:600px; position:relative; z-index:2;";
        imgContainer.appendChild(drinkCanvas);

        // 调用渲染引擎绘制（600/650 是缩放比例）
        if (drinkData.code) {
            renderThumbnailFromCode(drinkCanvas, drinkData.code, 600 / 650, true); 
        } else {
            drinkCanvas.innerHTML = `<div style="font-size:120px; display:flex; align-items:center; justify-content:center; height:100%;">🥤</div>`;
        }

    } else if (variantData) {
        // --- 情况 B: 这是一个带染色的新原料 ---
        nameEl.innerText = name;
        const img = document.createElement("img");
        img.id = "popupItemImage";
        img.className = "item-img";
        const fileName = variantData.baseImageName || variantData.name;
        img.src = `${imgBaseUrl}${fileName}.PNG`;

        if (variantData.defaultTint) {
            applyTintFilter(img, variantData.defaultTint);
        }
        imgContainer.appendChild(img);

    } else {
        // --- 情况 C: 这是一个普通物品（金币、素材等） ---
        nameEl.innerText = name;
        if (imgSrc) {
            const img = document.createElement("img");
            img.id = "popupItemImage";
            img.className = "item-img";
            img.src = imgSrc;
            imgContainer.appendChild(img);
        }
    }

    // 4. 显示弹窗
    overlay.style.display = "flex";
}
