      let selectedIngredients = new Set();
      function initDevInterface() {
        const listBase = document.getElementById("list-base");
        const listToppings = document.getElementById("list-toppings");

        if (!listBase || !listToppings) return;

        listBase.innerHTML = "";
        listToppings.innerHTML = "";
        selectedIngredients.clear();

        // 自动添加固定层
        ingredientsDB
          .filter((i) => i.isFixed)
          .forEach((i) => selectedIngredients.add(i.id));

        // --- 关键修改点：使用 Object.values() 来遍历对象 ---
        Object.values(unlockedIngredients).forEach((item) => {
          const btn = document.createElement("div");
          btn.className = "ingredient-btn";
          btn.innerText = item.name;
          btn.onclick = () => handleIngredientClick(item.id);
          btn.id = `btn-${item.id}`;

          if (item.type === "base") {
            listBase.appendChild(btn);
          } else {
            listToppings.appendChild(btn);
          }
        });

        updateCanvas();
      }

      function handleIngredientClick(id) {
        // 显示详情
        showIngredientInfo(id);

        // 切换选中
        if (selectedIngredients.has(id)) {
          selectedIngredients.delete(id);
          document.getElementById(`btn-${id}`).classList.remove("active");
        } else {
          selectedIngredients.add(id);
          document.getElementById(`btn-${id}`).classList.add("active");
        }

        updateCanvas();
      }

      /* --- 修复后的详情显示函数 (适配新数据库) --- */
      /* --- 修复后的详情显示函数 (信息完整版) --- */
      function showIngredientInfo(id) {
        const item = getIngredientById(id);
        if (!item) return;

        // 1. 切换显示状态
        document.getElementById("infoPlaceholder").style.display = "none";
        const infoCard = document.getElementById("ingredientInfo");
        infoCard.style.display = "flex";

        // 2. 填充基础信息 (名称、成本)
        document.getElementById("infoName").innerText = item.name;
        document.getElementById("infoCost").innerText = item.cost;

        // 3. 填充季节 (图标 + 文字)
        const seasonMap = { 夏: "☀️", 冬: "❄️", 全: "⭐" };
        const seasonEmoji = seasonMap[item.season] || "❓";
        // 这里我们只显示图标，或者你可以改成 seasonEmoji + item.season
        document.getElementById("infoSeason").innerText = seasonEmoji;

        // 4. 填充描述
        document.getElementById("infoDesc").innerText =
          item.desc || "暂无详细描述...";

        // 5. 填充标签 (带颜色和星星)
        const tagsContainer = document.getElementById("infoTags");
        tagsContainer.innerHTML = "";

        // 辅助函数：生成星星字符串
        const getStars = (num) => "★".repeat(num);

        // 渲染核心标签 (Core Tag)
        if (item.coreTags) {
          const span = document.createElement("span");
          // 使用与原料仓一致的颜色获取逻辑
          const color = getTagColor(item.coreTags.n);

          span.className = "tag-badge";
          // 强制覆盖样式以匹配颜色
          span.style.background = color;
          span.style.fontSize = "14px"; // 稍微调小一点适应卡片
          span.style.padding = "4px 10px";

          // 内容：名称 + 星级
          span.innerHTML = `${item.coreTags.n} <span style="opacity:0.8; margin-left:2px;">${getStars(item.coreTags.l)}</span>`;
          tagsContainer.appendChild(span);
        }

        // 渲染辅助标签 (Sub Tag)
        if (item.subTags) {
          const span = document.createElement("span");
          span.className = "tag-badge";
          span.style.background = "#9CA3AF"; // 灰色
          span.style.fontSize = "14px";
          span.style.padding = "4px 10px";

          span.innerHTML = `${item.subTags.n} <span style="opacity:0.8; margin-left:2px;">${getStars(item.subTags.l)}</span>`;
          tagsContainer.appendChild(span);
        }
      }
      function updateCanvas() {
    const canvas = document.getElementById("cupCanvas");
    if (!canvas) return;

    // 1. 彻底清空画布内容
    canvas.innerHTML = "";

    // 2. 【核心修复】：渲染全局奶茶背景
    // 检查 appSettings 是否存在以及是否选择了背景
    if (typeof appSettings !== 'undefined' && appSettings.drinkBackground) {
        const bgImg = document.createElement("img");
        // 拼接路径：基础URL + 背景名 + .PNG (注意大小写要匹配GitHub)
        bgImg.src = `${imgBaseUrl}${appSettings.drinkBackground}.PNG`;
        bgImg.className = "layer-img";
        bgImg.style.zIndex = "1"; // 设为 1，确保在所有原料之下
        bgImg.style.display = "block";
        bgImg.style.pointerEvents = "none";

        // 增加加载失败监听，方便调试
        bgImg.onerror = () => console.error("❌ 背景图加载失败:", bgImg.src);

        canvas.appendChild(bgImg);
        console.log("🖼️ 研发室背景已注入:", appSettings.drinkBackground);
    }

    // 3. 收集并排序选中的原料
    const activeItems = [];
    selectedIngredients.forEach((id) => {
        const item = getIngredientById(id);
        if (item) activeItems.push(item);
    });

    // 严格按 z 轴排序，如果 z 一样按 ID 排（保持视觉一致性）
    activeItems.sort((a, b) => {
        if (a.z !== b.z) return a.z - b.z;
        return a.id.localeCompare(b.id);
    });

    // 4. 渲染原料图层
    activeItems.forEach((item, idx) => {
        const img = document.createElement("img");
        const imgName = item.baseImageName || item.name;
        img.src = `${imgBaseUrl}${imgName}.PNG`;
        img.className = "layer-img";

        // 【关键】：原料的 zIndex 必须高于背景 (10 + idx)
        img.style.zIndex = 10 + idx; 
        canvas.appendChild(img); 

        // 处理染色滤镜
        if (item.defaultTint) {
            // 使用 setTimeout 确保图片标签已进入 DOM
            setTimeout(() => { applyTintFilter(img, item.defaultTint); }, 0);
        }
    });
}

// --- 强化版：全能初始化与场景恢复系统 ---
window.addEventListener("load", async () => {
    // 1. 基础 UI 准备
    const aiToggle = document.getElementById("ai-gen-toggle");
    const savedAiState = localStorage.getItem("milktea_ai_gen_enabled");
    if (aiToggle) {
        aiToggle.checked = (savedAiState === null) ? true : (savedAiState === "true");
        aiToggle.onchange = () => { localStorage.setItem("milktea_ai_gen_enabled", aiToggle.checked); };
    }
    initForumCleanupUI();
    setScale();

    // 2. 【核心】等待并解析 MVU 数据
    try {
        // 等待酒馆 MVU 插件初始化
        await waitGlobalInitialized("Mvu");

        // 获取当前楼层数据
        const variables = Mvu.getMvuData({ type: 'message', message_id: getCurrentMessageId() });
        const sd = _.get(variables, 'stat_data');

        if (sd) {
            // 将云端数据同步到本地变量
            if (sd.shopConfig) shopConfig = sd.shopConfig;
            if (sd.appSettings) appSettings = sd.appSettings;
            if (sd.unlockedIngredients) unlockedIngredients = sd.unlockedIngredients;
            if (sd.customersDB) customersDB = sd.customersDB;
            if (sd.shopMenu) shopMenu = sd.shopMenu;
            if (sd.shopFinancials) shopFinancials = sd.shopFinancials;
            if (sd.phoneChatDB) phoneChatDB = sd.phoneChatDB;
            if (sd.phoneTaskDB) phoneTaskDB = sd.phoneTaskDB;
            if (sd.phoneMatchDB) phoneMatchDB = sd.phoneMatchDB;
            if (sd.matchResultsDB) matchResultsDB = sd.matchResultsDB;
            if (sd.phoneShopDB) phoneShopDB = sd.phoneShopDB;
            if (sd.phoneForumDB) phoneForumDB = sd.phoneForumDB;
            if (sd.worldConfig) worldConfig = sd.worldConfig;
            if (sd.tempDrinkStats) {
                // 缝补逻辑：如果 AI 返回的数据缺代码，从本地备份找
                const localBackup = JSON.parse(localStorage.getItem('milktea_dev_backup') || '{}');
                editorState.tempStats = {
                    ...sd.tempDrinkStats,
                    code: sd.tempDrinkStats.code || localBackup.code || null,
                    ingredients: (sd.tempDrinkStats.ingredients?.length > 0) ? sd.tempDrinkStats.ingredients : (localBackup.ingredients || [])
                };
            }
            console.log("✅ 经营数据已同步");
        }
    } catch (e) {
        console.error("❌ MVU 解析失败:", e);
    }

    // 3. 【核心】从最新 AI 消息提取剧情对白
    try {
        // A. 获取本界面所在的楼层 ID
        const myMsgId = getCurrentMessageId();

        // B. 获取本楼层数据
        const msgData = TavernHelper.getChatMessages(myMsgId);

        if (msgData && msgData.length > 0) {
            const currentMsg = msgData[0];
            if (currentMsg && currentMsg.message) {
                // 1. 找出本楼层内所有的 <dialogtext> 块 (考虑到可能有多个标签)
                const regex = /<dialogtext>\s*([\s\S]*?)\s*<\/dialogtext>/g;
                const allMatches = Array.from(currentMsg.message.matchAll(regex));

                if (allMatches.length > 0) {
                    // 2. 取楼层内最后一对标签的内容
                    let rawContent = allMatches[allMatches.length - 1][1].trim();

                    // 3. 清洗 HTML 注释 (解决秦宿注释导致没字的问题)
                    rawContent = rawContent.replace(/<!--[\s\S]*?-->/g, "");

                    // 4. 精准定位 JSON 数组 [ ... ]
                    const start = rawContent.indexOf('[');
                    const end = rawContent.lastIndexOf(']');

                    if (start !== -1 && end !== -1) {
                        const jsonString = rawContent.substring(start, end + 1);
                        try {
                            const parsed = JSON.parse(jsonString);
                            if (Array.isArray(parsed)) {
                                dialogData = parsed;
                                console.log(`🎬 成功从本楼层(ID:${myMsgId})提取剧情:`, dialogData.length, "条");
                            }
                        } catch (e) { console.error("❌ JSON 解析失败:", e); }
                    }
                }
            }
        }
    }catch (e) { console.error("消息读取异常", e); }

    // 4. 执行 UI 渲染
    wakeUpMainHallUI(); 
    renderCustomerList();
    initShowcaseKey();
    updateNarrativeModeUI();

    // 5. 场景恢复处理器 (处理队列里的任务)
    await processSceneQueue(); 

    // 如果队列里没有特定场景，默认显示手机桌面
    const currentActiveLayer = document.querySelector('.popup-layer[style*="display: flex"]');
    if (!currentActiveLayer) {
        navigateToPhone("home");
    }
});



