      // 3. 滤镜与辅助函数 (修改 applyEditorFilters)
      // --- 修复版：编辑器专用滤镜应用函数 ---
      function applyEditorFilters(img, layer) {
        // 1. 先设置透明度 (Opacity)
        // 透明度通常作为 style 单独属性性能更好，或者放入 filter 也可以
        img.style.opacity = layer.opacity / 100;

        // 2. 构建基础滤镜字符串 (亮度 Brightness、对比度 Contrast)
        // 注意：这里不包含染色逻辑了，染色交给通用函数处理
        let baseFilter = `brightness(${layer.brightness}%) contrast(${layer.contrast}%)`;

        // 3. 应用基础滤镜
        img.style.filter = baseFilter;

        // 4. 处理染色 (Tint)
        // 关键点：调用我们刚修复的全局兼容版 applyTintFilter
        if (layer.tintColor) {
          // applyTintFilter 会读取当前的 filter (亮度/对比度)，然后把 SVG 染色滤镜追加上去
          // 这样就既保留了亮度对比度，又加上了颜色，且兼容 iOS
          applyTintFilter(img, layer.tintColor);
        }
      }
      function selectLayer(id) {
        editorState.selectedId = id;
