        title.innerText = `正在调整: ${layer.name}`;
        content.style.opacity = "1";
        content.style.pointerEvents = "auto";

        document.getElementById("editor-tint").value =
          layer.tintColor || "#000000";
        document.getElementById("val-opacity").innerText = layer.opacity + "%";
        document.getElementById("val-brightness").innerText =
          layer.brightness + "%"; // 更新亮度
        document.getElementById("val-contrast").innerText =
          layer.contrast + "%"; // 更新对比度
      }

      function getSelectedLayer() {
        return editorState.layers.find((l) => l.id === editorState.selectedId);
      }

      function moveLayer(dx, dy) {
        const layer = getSelectedLayer();
