      }

      function moveLayerZ(dir) {
        const layer = getSelectedLayer();
        if (!layer) return;
        const index = editorState.layers.indexOf(layer);
        if (dir === "up" && index < editorState.layers.length - 1) {
          [editorState.layers[index], editorState.layers[index + 1]] = [
            editorState.layers[index + 1],
            editorState.layers[index],
          ];
          editorState.layers.forEach((l, i) => (l.zIndex = i));
        } else if (dir === "down" && index > 0) {
          [editorState.layers[index], editorState.layers[index - 1]] = [
            editorState.layers[index - 1],
            editorState.layers[index],
          ];
          editorState.layers.forEach((l, i) => (l.zIndex = i));
        }
        renderEditor();
      }

