      /* --- 奶茶评分系统 (核心算法 - 高标准版) --- */
      function calculateRating(items) {
        let sumStars = 0;
        let sumA = 0;
        let sumB = 0;

        const typeA = ["清爽", "微苦", "脆爽", "清冽"];
        const typeB = ["醇厚", "甜腻", "绵密", "黏腻"];

        items.forEach((item) => {
          if (item.coreTags) {
            const star = item.coreTags.l;
            sumStars += star;
            if (typeA.some((t) => item.coreTags.n.includes(t))) sumA += star;
            if (typeB.some((t) => item.coreTags.n.includes(t))) sumB += star;
          }
          if (item.subTags) {
            const star = item.subTags.l;
            sumStars += star;
            if (typeA.some((t) => item.subTags.n.includes(t))) sumA += star;
            if (typeB.some((t) => item.subTags.n.includes(t))) sumB += star;
          }
        });

        // 1. 品质分计算 (已提高标准)
        // 之前很容易拿5星，现在需要约 30+ 星数 (相当于6-7个丰富原料) 才能5星
        let qualityScore = 1;
        if (sumStars >= 60) qualityScore = 5;
        else if (sumStars >= 52) qualityScore = 4;
        else if (sumStars >= 43) qualityScore = 3;
        else if (sumStars >= 34) qualityScore = 2;

        // 2. 口感分计算
        const diff = Math.abs(sumA - sumB);
        let balanceScore = 1;
        let comment = "";

        if (diff <= 1) {
          balanceScore = 5;
          comment = "【黄金比例】A类与B类风味完美互补，口感极致平衡！";
        } else if (diff <= 3) {
          balanceScore = 4;
          comment = "【优质组合】风味鲜明且协调，有独特的记忆点。";
        } else if (diff <= 6) {
          balanceScore = 3;
          comment =
            sumA > sumB
              ? "风味明显偏向清爽刺激，略显单薄。"
              : "风味偏向浓郁甜腻，喝多容易腻。";
        } else {
          balanceScore = 2;
          comment =
            sumA > sumB
              ? "极端清爽型，像是在喝凉水，缺乏奶茶的快乐。"
              : "重度甜腻风暴，建议搭配健胃消食片食用。";
        }

        // 3. 最终评分
        const finalScore = ((qualityScore + balanceScore) / 2).toFixed(1);

        // 4. 加工建议
        let advice = "建议去冰/温饮";
        if (sumA > sumB) advice = "建议加冰 (+0.5口感)";
        else if (sumB > sumA) advice = "建议热饮 (+0.5口感)";

        return {
          quality: qualityScore,
          balance: balanceScore,
          final: finalScore,
          sumStars,
          sumA,
          sumB,
          diff,
          comment,
          advice,
        };
      }
// --- 材质大师版：柔光染色函数 (解决浅色变白、深色不显色问题) ---
/**
 * 强化版染色函数：具备自动垃圾回收功能，防止 iOS 内存溢出
 */
 function applyTintFilter(imgEl, hexColor) {
    if (!hexColor || !imgEl) return;

    // --- 1. 垃圾回收：物理删除该图片之前的旧滤镜节点 ---
    // 我们通过自定义属性 data-active-filter 记录正在使用的滤镜 ID
    const oldFilterId = imgEl.getAttribute('data-active-filter');
    if (oldFilterId) {
        const oldSvg = document.getElementById('wrapper-' + oldFilterId);
        if (oldSvg) {
            oldSvg.remove(); // 从 DOM 中彻底物理删除，释放显存
        }
    }

    // --- 2. 生成新 ID 并记录 ---
    const uniqueId = "tint-" + Math.random().toString(36).substr(2, 9);
    imgEl.setAttribute('data-active-filter', uniqueId);

    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");

    // 给外层增加 ID 方便精准删除
    svg.id = 'wrapper-' + uniqueId; 
    svg.setAttribute("width", "0");
    svg.setAttribute("height", "0");
    svg.style.cssText = "position:absolute; pointer-events:none; visibility:hidden;";

    const filter = document.createElementNS(svgNS, "filter");
    filter.setAttribute("id", uniqueId);
    filter.setAttribute("color-interpolation-filters", "sRGB");

    // 步骤 1: 提取纹理
    const feColorMatrix = document.createElementNS(svgNS, "feColorMatrix");
    feColorMatrix.setAttribute("type", "matrix");
    feColorMatrix.setAttribute("values", `
        0.33 0.33 0.33 0 0.1
        0.33 0.33 0.33 0 0.1
        0.33 0.33 0.33 0 0.1
        0    0    0    1 0
    `);
    feColorMatrix.setAttribute("result", "texture");

    // 步骤 2: 颜色注入
    const feFlood = document.createElementNS(svgNS, "feFlood");
    feFlood.setAttribute("flood-color", hexColor);
    feFlood.setAttribute("result", "colorBlock");

    const feComposite = document.createElementNS(svgNS, "feComposite");
    feComposite.setAttribute("in", "colorBlock");
    feComposite.setAttribute("in2", "SourceAlpha");
    feComposite.setAttribute("operator", "in");
    feComposite.setAttribute("result", "coloredShape");

    // 步骤 3: 柔光混合 (iOS 显存消耗大户，确保旧的已删)
    const feBlend = document.createElementNS(svgNS, "feBlend");
    feBlend.setAttribute("in", "texture");
    feBlend.setAttribute("in2", "coloredShape");
    feBlend.setAttribute("mode", "soft-light");

    filter.appendChild(feColorMatrix);
    filter.appendChild(feFlood);
    filter.appendChild(feComposite);
    filter.appendChild(feBlend);
    svg.appendChild(filter);

    // --- 3. 挂载到专门的存储容器 ---
    let container = document.getElementById("svg-filter-storage");
    if (!container) {
        container = document.createElement("div");
        container.id = "svg-filter-storage";
        container.style.cssText = "height:0; width:0; overflow:hidden; position:absolute;";
        document.body.appendChild(container);
    }
    container.appendChild(svg);

    // --- 4. 应用滤镜 ---
    // 强制先重置一次 filter 属性，触发 Safari 的重绘机制
    const currentFilter = imgEl.style.filter.includes('url') ? '' : imgEl.style.filter;

    requestAnimationFrame(() => {
        // 将原有的 filter 字符串和新的 url(#id) 拼在一起
        imgEl.style.filter = `${currentFilter} url(#${uniqueId})`.trim();
    });
}


