        // --- 核心修复：1. 透明度单独使用 opacity 属性 ---
        img.style.opacity = layer.opacity / 100;

        // --- 核心修复：2. 滤镜只写亮度和对比度 ---
        img.style.filter = `brightness(${layer.brightness}%) contrast(${layer.contrast}%)`;

        wrapper.appendChild(img);

        // --- 核心修复：3. 染色逻辑会追加在 filter 后面，不会覆盖 opacity ---
        if (layer.tintColor) {
            setTimeout(() => { applyTintFilter(img, layer.tintColor); }, 0);
        }
    });
