        wrapper.appendChild(bgImg);
    }

    layers.sort((a, b) => a.zIndex - b.zIndex).forEach((layer) => {
        const img = document.createElement("img");
        img.src = layer.src;
        img.style.cssText = `position:absolute; left:${layer.x}px; top:${layer.y}px; width:${layer.width * layer.scale}px; height:${layer.height * layer.scale}px; z-index:${layer.zIndex};`;

