        const coreStar = item.coreTags ? item.coreTags.l : 0;
        const subStar = item.subTags ? item.subTags.l : 0;
        totalStars += (coreStar + subStar);
        if (item.coreTags) {
            if (typeA.some((t) => item.coreTags.n.includes(t))) sumA += coreStar;
            if (typeB.some((t) => item.coreTags.n.includes(t))) sumB += coreStar;
        }
        if (item.subTags) {
            if (typeA.some((t) => item.subTags.n.includes(t))) sumA += subStar;
            if (typeB.some((t) => item.subTags.n.includes(t))) sumB += subStar;
        }
        allLayersForCode.push(createDefaultLayer(item, 10 + index));
    });

    const frontWall = ingredientsDB.find(i => i.id === 'wall_front');
