        // 初始参数：[索引, x:0, y:0, z, scale:100, opacity:100, bright:100, contrast:100, tint]
        return [dbIdx, 0, 0, l.zIndex, 100, 100, 100, 100, tint].join(",");
    }).filter(Boolean).join(";");

    const complexCode = btoa(rawStr); 

