    // 计算星级
/* --- 找到这一段并进行修改 --- */

// 1. 获取难度修正系数
let diffModifier = 1.0; // 标准
if (ratingDifficulty === 'easy') diffModifier = 1.35; // 轻松：原料价值提升35%
if (ratingDifficulty === 'hard') diffModifier = 0.75; // 困难：原料价值削减25%

// 2. 应用修正系数到总星数
const adjustedTotalStars = totalStars * diffModifier;

// 3. 使用修正后的分数进行区间判定
let qStars = 1.0;
if (adjustedTotalStars >= 44) qStars = 4.8 + (Math.min(adjustedTotalStars, 55) - 44) / 11 * 0.2; 
else if (adjustedTotalStars >= 32) qStars = 3.8 + (adjustedTotalStars - 32) / 12 * 1.0;
else if (adjustedTotalStars >= 20) qStars = 2.5 + (adjustedTotalStars - 20) / 12 * 1.3;
else qStars = 1.0 + (adjustedTotalStars / 20) * 1.5;

qStars = Math.min(5, qStars).toFixed(1);

// 口感分(tStars)也受一点难度影响：难度越高，平衡要求越苛刻
let balancePenalty = Math.abs(sumA - sumB);
if (ratingDifficulty === 'hard') balancePenalty *= 1.5; // 困难模式下，配比歪一点扣分更多
if (ratingDifficulty === 'easy') balancePenalty *= 0.5; // 轻松模式下，配比歪了也不怎么扣分

let tStars = Math.max(0, 5 - balancePenalty / 5).toFixed(1);
    let fRating = ((parseFloat(qStars) + parseFloat(tStars)) / 2).toFixed(1);

    // 4. 保存到云端 (MVU)
    try {
        await waitGlobalInitialized("Mvu");
        const mvuData = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });

        const tempStats = {
            name: isAiEnabled ? '正在等待 AI 命名...' : '新研发奶茶',
