            desc: isAiEnabled ? "正在连接食客评审团..." : "快为这杯新品写段介绍吧。",
            refreshingScore: sumA,
            mellowScore: sumB,
            finalRating: parseFloat(fRating),
            qualityStars: parseFloat(qStars),
            tasteStars: parseFloat(tStars),
            popularity: 1,
            createdAt: new Date().toLocaleString(),
            sales: 0,
            isShowcase: false,
            code: complexCode 
        };

        mvuData.stat_data.tempDrinkStats = tempStats;
        editorState.tempStats = tempStats; 

        // --- 核心逻辑：将“工坊精修”加入场景队列 ---
        if (!appSettings.pendingScenes) appSettings.pendingScenes = [];
        if (!appSettings.pendingScenes.includes('layer-result')) {
