        }
        mvuData.stat_data.appSettings = appSettings;

        await Mvu.replaceMvuData(mvuData, { type: "message", message_id: getCurrentMessageId() });

        // 5. 【分支跳转逻辑】
        if (isAiEnabled) {
            // --- AI 协助模式：直接关闭，回大堂 ---
            closeLayer('layer-dev');

            // 压入同步缓存
            const researchMessage = `用 ${ingredientNames.join('、')} 研发奶茶（品质${qStars}星，口感${tStars}星）`;
            queueTavernMessage(researchMessage); 

            showSysAlert("🥤 研发蓝图已准备好！\n请点击右上角【同步决策】通知评审团。\n(评审完后将自动开启精修界面)");
        } else {
