      // 修改压缩算法
      function generateShortCode() {
    if (editorState.layers.length === 0) return "";
    const masterList = getMasterIngredientList();

    const rawStr = editorState.layers
        .map((l) => {
            const dbIdx = masterList.findIndex((db) => db.id === l.id);
            if (dbIdx === -1) return null;

            const tint = l.tintColor ? l.tintColor.replace("#", "") : "";
            // 恢复旧版参数：[索引, x, y, z, 缩放, 不透明度, 亮度, 对比度, 颜色]
            return [
                dbIdx,
                Math.round(l.x),
                Math.round(l.y),
                l.zIndex,
                Math.round(l.scale * 100),
                l.opacity,
                l.brightness,
                l.contrast,
                tint,
            ].join(",");
        })
        .filter(Boolean)
        .join(";");

    return btoa(rawStr); // 返回 Base64 格式
}


function parseShortCode(code) {
    if (!code) return null;

    // --- 新版极简码解析 (仅用于读取) ---
    if (code.startsWith("v2|")) {
        try {
            const masterList = getMasterIngredientList();
            const parts = code.split("|").slice(1);
            let layers = [];

            // 1. 自动注入后壁
            const backWall = masterList.find(i => i.id === 'wall_back');
            if (backWall) layers.push(createDefaultLayer(backWall, 1));

            // 2. 解析中间部分
            parts.forEach((p, index) => {
                const [idxStr, tint] = p.split(",");
                const dbItem = masterList[parseInt(idxStr)];
                if (dbItem) {
                    const layer = createDefaultLayer(dbItem, 10 + index);
                    if (tint && tint.length >= 3) layer.tintColor = "#" + tint;
                    layers.push(layer);
                }
            });

            // 3. 自动注入前壁
            const frontWall = masterList.find(i => i.id === 'wall_front');
            if (frontWall) layers.push(createDefaultLayer(frontWall, 999));

            return layers;
        } catch (e) {
            console.error("v2 码解析失败", e);
            return null;
        }
    }

    // --- 旧版 Base64 码解析 (保持完全兼容) ---
    try {
        const rawStr = atob(code);
        const masterList = getMasterIngredientList();
        return rawStr.split(";").map((str) => {
            const v = str.split(",");
            const dbItem = masterList[parseInt(v[0])]; // 这里的 v[0] 对应的就是母库索引
            if (!dbItem) return null;

            return {
              uid: "lyr-" + Math.random().toString(36).substr(2, 9), // 核心修复
    id: dbItem.id,
    name: dbItem.name,
                src: `${imgBaseUrl}${dbItem.baseImageName || dbItem.name}.PNG`,
                x: parseInt(v[1]) || 0,
                y: parseInt(v[2]) || 0,
                zIndex: parseInt(v[3]) || 0,
                width: 650, height: 650,
                scale: (parseInt(v[4]) || 100) / 100,
                opacity: parseInt(v[5]) || 100,
                brightness: parseInt(v[6]) || 100,
                contrast: parseInt(v[7]) || 100,
                tintColor: (v[8] && v[8].length >= 3) ? "#" + v[8] : null,
            };
        }).filter(Boolean);
    } catch (e) { return null; }
  }
// 辅助函数：创建一个标准状态的图层
function createDefaultLayer(dbItem, z) {
    return {
        uid: "lyr-" + Math.random().toString(36).substr(2, 9), // 增加唯一UID
        id: dbItem.id,
        name: dbItem.name,
        src: `${imgBaseUrl}${dbItem.baseImageName || dbItem.name}.PNG`,
        x: 0, y: 0,
        width: 650, height: 650,
        scale: 1,
        zIndex: z,
        opacity: 100,
        brightness: 100,
        contrast: 100,
        tintColor: dbItem.defaultTint || null
    };
}

