        if (weather === "晴天") {
          // 1. 夏天和冬天的晴天：指向通用的“白天-晴天”或“黑夜-晴天”
          if (season === "夏天" || season === "冬天") {
            // --- 修正点：改用反引号 ` ---
            fileName = `${time}-晴天`; 
          }
          // 2. 春天和秋天的晴天：维持 [季节-时段]
          else {
            fileName = `${season}-${time}`;
          }
        }
        // 3. 非晴天情况（雨、雪、阴）：维持 [时段-天气]
        else {
          fileName = `${time}-${weather}`;
        }

        // 拼接完整 URL (注意后缀名大小写要与图床一致)
        const finalUrl = `${basePath}${fileName}.png`;

