// --- 核心：提交作品、包含评委元数据、同步并删除记录 ---
async function confirmTaskSubmission() {
    // 1. 基础检查
    if (!selectedTaskDrinkKey) {
        alert("请先选择一款饮品！");
        return;
    }

    let chatMsg = "";
    let drinkData = shopMenu[selectedTaskDrinkKey];

    // 2. 分支处理：参加比赛
    if (isParticipatingMatch) {
        const matchData = phoneMatchDB[currentMatchId];
        if (matchData) {
            // 解析评委真实姓名
            const judgeNames = matchData.judges.map(id => customersDB[id] ? customersDB[id].name : id).join("、");

            // --- 【核心增强：构建详尽的比赛信息】 ---
            chatMsg = `【提交参赛作品】
赛事名称：${currentMatchId}
赛事简介：${matchData.desc}
参赛要求：${matchData.requirement}
评审团：${judgeNames}
最终奖励：${matchData.reward}

我的参赛作品：【${selectedTaskDrinkKey}】
作品描述：${drinkData.desc || "店长秘制特调"}
作品属性：品质${drinkData.qualityStars}星 / 口感${drinkData.tasteStars}星 / 综合${drinkData.finalRating}分
风味倾向：清爽度(${drinkData.refreshingScore}) / 醇厚度(${drinkData.mellowScore})

请评审团根据以上作品表现与赛事要求的匹配程度，给出专业评审结果。`;

            // 管理场景队列
            if (!appSettings.pendingScenes) appSettings.pendingScenes = [];
            if (!appSettings.pendingScenes.includes('match-result')) {
                appSettings.pendingScenes.unshift('match-result'); // 比赛结果优先级最高
            }

            // 本地缓存以便恢复
            localStorage.setItem("milktea_target_scene", "match-result");
            localStorage.setItem("milktea_match_id", currentMatchId);
            localStorage.setItem("milktea_submitted_drink", selectedTaskDrinkKey);

            // 从待办列表中移除该比赛
            delete phoneMatchDB[currentMatchId];
        }
    } 
    // 3. 分支处理：交付委托任务
    else {
        const taskData = phoneTaskDB[currentChatId];
        if (taskData) {
            chatMsg = `【交付奶茶委托】
委托人：${taskData.name}
背景故事：${taskData.backstory}
顾客要求：${taskData.constraints.join(' | ')}
预期奖励：${taskData.reward}

提交饮品：【${selectedTaskDrinkKey}】
饮品表现：品质${drinkData.qualityStars}星 / 口感${drinkData.tasteStars}星

请顾客根据饮品是否满足要求给出评价。`;

            delete phoneTaskDB[currentChatId];
        }
    }

    // 4. 【核心同步：存入缓存】
    queueTavernMessage(chatMsg);

    // 5. 持久化到云端存档 (MVU)
    try {
        await waitGlobalInitialized("Mvu");
        const mvuData = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });

        if (!mvuData.stat_data) mvuData.stat_data = {};
        mvuData.stat_data.phoneMatchDB = phoneMatchDB;
        mvuData.stat_data.phoneTaskDB = phoneTaskDB;
        mvuData.stat_data.appSettings = appSettings;

        await Mvu.replaceMvuData(mvuData, { type: "message", message_id: getCurrentMessageId() });

        // 6. UI 反馈
        closeLayer('layer-menu'); // 关闭配方列表

        if (isParticipatingMatch) {
            showSysAlert(`🏆 参赛作品【${selectedTaskDrinkKey}】已送往比赛现场！\n请点击右上角【同步决策】开启评审。`);
        } else {
            showSysAlert(`🥤 委托饮品【${selectedTaskDrinkKey}】已打包！\n请点击右上角【同步决策】通知顾客。`);
        }

    } catch (e) {
        console.error("❌ 存档失败:", e);
    }

    // 重置提交标志
    isSubmittingTask = false;
    isParticipatingMatch = false;
}
