      // 处理 Buff/Debuff 动作
      async function handleEffectAction(id, action) {
    const effectIndex = shopConfig.activeEffects.findIndex(e => e.id === id);
    if (effectIndex === -1) return;

    const effect = shopConfig.activeEffects[effectIndex];

    // 获取剧情决策面板的 DOM 元素
    const choiceBox = document.getElementById("choiceOverlay");
    const titleEl = choiceBox.querySelector(".choice-title");
    const confirmBtn = choiceBox.querySelector(".confirm-choice");
    const cancelBtn = choiceBox.querySelector(".cancel-choice");

    if (action === 'clear' && effect.type === 'debuff') {
        const cost = effect.costToClear || 0;

        // 1. 设置弹窗标题
        titleEl.innerText = `确定要支付 ¥${cost} 紧急处理 "${effect.name}" 吗？`;

        // 2. 隐藏不需要的输入框和剧情固定选项，只留底部的确认/取消
        document.getElementById("fixedOptions").style.display = "none";
        document.querySelector(".custom-input-wrap").style.display = "none";

        // 3. 显示弹窗
        choiceBox.style.display = "flex";

        // 4. 劫持“确认”按钮的点击事件
        confirmBtn.onclick = async function() {
            const success = processTransaction(cost, `处理异常: ${effect.name}`);
            if (success) {
                shopConfig.activeEffects.splice(effectIndex, 1);
                renderShopAdmin(); // 刷新管理面板UI
                await saveShopDataToMvu(); // 同步到存档
            }
            // 还原界面和原始事件，关闭弹窗
            restoreChoiceSystem();
        };

        // 5. 劫持“取消”按钮的点击事件
        cancelBtn.onclick = function() {
            restoreChoiceSystem();
        };
    } 
    // 顺便把 Buff 续期的 confirm 也改了，保持视觉统一！
    else if (action === 'renew' && effect.type === 'buff') {
        const cost = effect.costToRenew || 0;

        titleEl.innerText = `确定支付 ¥${cost} 为 "${effect.name}" 续期 3 天吗？`;
        document.getElementById("fixedOptions").style.display = "none";
        document.querySelector(".custom-input-wrap").style.display = "none";
        choiceBox.style.display = "flex";

        confirmBtn.onclick = async function() {
            const success = processTransaction(cost, `增益续期: ${effect.name}`);
            if (success) {
                effect.remainingDays += 3;
                renderShopAdmin();
                await saveShopDataToMvu();
            }
            restoreChoiceSystem();
        };

        cancelBtn.onclick = function() {
            restoreChoiceSystem();
        };
    }

    // 辅助闭包函数：用于还原决策面板的原始状态
    function restoreChoiceSystem() {
        document.getElementById("fixedOptions").style.display = "block";
        document.querySelector(".custom-input-wrap").style.display = "block";
        confirmBtn.onclick = confirmUserChoice; // 还原为最初的剧情决策事件
        cancelBtn.onclick = () => closeChoiceSystem(); // 还原为单纯的关闭
        closeChoiceSystem();
    }
}

