      // --- 辅助：处理财务变动 (扣钱、记账、更新UI) ---
function processTransaction(amount, itemName, type = 'expense') {
    const cost = Math.abs(amount);

    // 1. 检查余额
    if (shopFinancials.currentBalance < cost) {
      showSysAlert("资金不足！快去卖奶茶赚钱吧。");
        return false;
    }

    // 2. 变更余额
    shopFinancials.currentBalance -= cost;
    shopFinancials.lastUpdate = new Date().toLocaleString();

    // 3. 添加账单记录 (按照你的 RecordSchema)
    const now = new Date();
    const dateStr = `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}`;

    shopFinancials.records.unshift({
        date: dateStr,
        item: itemName,
        amount: type === 'income' ? cost : -cost,
        type: type
    });

    // 限制记录数量，防止存档过大
    if (shopFinancials.records.length > 20) shopFinancials.records.pop();

    // 4. 同步全局金钱显示
    syncGlobalBalance();
    return true;
}
async function syncShopName(newName) {
