}



async function buyMarketBuff(buffId) {
    const marketIndex = shopConfig.buffMarket.findIndex(i => i.id === buffId);
    if (marketIndex === -1) return;

    const item = shopConfig.buffMarket[marketIndex];

    // 获取剧情决策面板的 DOM 元素
    const choiceBox = document.getElementById("choiceOverlay");
