/**
 * 根据评分计算全城动态排名
 * @param {number} rating - 当前店铺评分
 * @param {string} myShopName - 店名
 * @returns {number} 排名
 */
 function calculateCityRank(rating, myShopName) {
    // 1. 获取所有预设店铺并排序
    const allShops = Object.entries(phoneShopDB).map(([name, data]) => ({
        name: name,
        rating: data.rating || 0,
        isPlayer: (data.owner === "{{user}}")
    }));

    allShops.sort((a, b) => b.rating - a.rating);

    // 2. 找到玩家在“种子选手”中的索引
    const playerIndex = allShops.findIndex(s => s.name === myShopName || s.isPlayer);
    const playerInTopCount = playerIndex + 1;

    // 3. 逻辑：如果在前 8 名，直接返回真实排名
    if (playerInTopCount <= 8 && rating >= 4.0) {
        return playerInTopCount;
    }

    // 4. 逻辑：如果评级较低，模拟全城数千家店的竞争压力
    // 算法参考：4.0分为基准(第10名)，每下降0.1分，排名掉落 15-20 位
    const baseRank = 10;
    const ratingGap = 4.2 - rating; // 与顶尖水平的差距
    if (ratingGap <= 0) return playerInTopCount; // 哪怕是4.9分没进前8，也按实际排

    // 模拟全城排位计算
    let simulatedOffset = Math.floor(ratingGap * 150); 
    // 比如：3.7分，Gap是0.5。 0.5 * 150 = 75名。 10 + 75 = 85名。

    return baseRank + simulatedOffset;
}

