                    desc: item.desc || "开发者模式解锁的原料",
                    coreTags: item.coreTags || { n: "特调", l: 2 }
                };
            }
        });

        // 2. 同步到 MVU 数据对象
        if (!mvuData.stat_data.unlockedIngredients) mvuData.stat_data.unlockedIngredients = {};

        // 深度合并本地已解锁的和母库中的
        Object.values(unlockedIngredients).forEach(item => {
            mvuData.stat_data.unlockedIngredients[item.id] = item;
        });

        // 3. 生成所有原料的名字字符串（用于 AI 识别）
        const allNames = Object.values(unlockedIngredients).map(i => i.name).join('、');
        mvuData.stat_data.unlockedIngredientListStr = allNames;

        // 4. 持久化保存
        await Mvu.replaceMvuData(mvuData, { type: "message", message_id: getCurrentMessageId() });

        // 5. 刷新相关 UI
        if (typeof initDevInterface === 'function') initDevInterface(); // 刷新研发室列表
        if (typeof renderMaterialStock === 'function') renderMaterialStock('all'); // 刷新原料仓

        showSysAlert("✨ [店长特权] 进货渠道已全部打通！所有原料已解锁。");

    } catch (e) {
        console.error("作弊模式执行失败:", e);
        alert("解锁失败，请检查脚本环境。");
    }
}
// 提交逻辑：同时抓取 星星 和 文本框内容
async function submitReview() {
    const userTypedText = document.getElementById("commentText").value.trim();
    const anonNick = document.getElementById("anon-nickname").value.trim() || "匿名食客";

    if (!userTypedText) {
        showSysAlert("请输入内容哦！");
        return;
    }

    const senderName = isCommentOwner ? `${shopConfig.identity.name} (店长)` : anonNick;
    const finalMsg = currentReplyTarget ? `@${currentReplyTarget} ${userTypedText}` : userTypedText;

    try {
        await waitGlobalInitialized("Mvu");
        const mvuData = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        const timeStr = "刚刚";

        if (!mvuData.stat_data.phoneShopDB) mvuData.stat_data.phoneShopDB = phoneShopDB;
        if (!mvuData.stat_data.phoneForumDB) mvuData.stat_data.phoneForumDB = phoneForumDB;

        if (currentCommentContext === 'create-post') {
            // --- 【核心修改：递增 ID 生成逻辑】 ---
            const allPostKeys = Object.keys(mvuData.stat_data.phoneForumDB);
            let maxIdNum = 0;

            // 遍历现有 ID，提取数字部分并找最大值
            allPostKeys.forEach(key => {
                const match = key.match(/\d+/); // 提取数字
                if (match) {
                    const num = parseInt(match[0]);
                    if (num > maxIdNum) maxIdNum = num;
                }
            });

            // 生成新 ID：最大值 + 1，并补齐 3 位数字（如 005）
            const nextIdNum = maxIdNum + 1;
            const newPostId = "post_" + nextIdNum.toString().padStart(3, '0');

            mvuData.stat_data.phoneForumDB[newPostId] = {
                id: newPostId,
                authorId: "default", 
                authorName: senderName,
                time: timeStr,
                content: userTypedText,
                media: [], 
                likes: 0,
                replies: []
            };
            phoneForumDB = mvuData.stat_data.phoneForumDB;
            currentForumPage = 1; // 重置到第一页以看到新贴
            console.log("✅ 成功发布新帖子，自动分配 ID:", newPostId);

        } else if (currentCommentContext === 'forum') {
            // --- 论坛回帖逻辑 (保持不变) ---
            const post = mvuData.stat_data.phoneForumDB[currentForumPostId];
            if (post) {
                if (!post.replies) post.replies = [];
                post.replies.push({ user: senderName, text: finalMsg, time: timeStr });
            }
            phoneForumDB = mvuData.stat_data.phoneForumDB;
        } else if (currentCommentContext === 'shop') {
            // --- 店铺评价逻辑 (保持不变) ---
            const shop = mvuData.stat_data.phoneShopDB[currentCommentShop];
            if (currentReplyTarget) {
                const targetReview = shop.reviews.find(r => r.user === currentReplyTarget);
                if (targetReview) {
                    if (!targetReview.replies) targetReview.replies = [];
                    targetReview.replies.push({ user: senderName, text: finalMsg, time: timeStr });
                }
            } else {
                if (!shop.reviews) shop.reviews = [];
                shop.reviews.unshift({
                    user: senderName, rate: currentCommentStars, text: finalMsg, time: timeStr, replies: []
                });
            }
            phoneShopDB = mvuData.stat_data.phoneShopDB;
        }

        await Mvu.replaceMvuData(mvuData, { type: "message", message_id: getCurrentMessageId() });
        await performForumCleanup();
        closeCommentModal();

        // 界面刷新
        if (currentCommentContext === 'create-post' || currentCommentContext === 'forum') {
            renderForumList();
            if (currentCommentContext === 'forum' && document.getElementById("page-forum-detail").classList.contains("active")) {
                openForumDetail(currentForumPostId);
            }
        } else {
            openReviewDetail(currentCommentShop);
        }

        // 向酒馆存入缓存 (由同步按钮发送)
        if (window.TavernHelper && window.TavernHelper.createChatMessages) {
            let actionDesc = currentCommentContext === 'create-post' ? "发布了新帖" : "发表了评论";
            let locationDesc = currentCommentContext === 'shop' ? `店铺[${currentCommentShop}]` : "超话论坛";
            const tavernMsg = `[手机动作] {{user}}以【${senderName}】身份，在手机【${locationDesc}】${actionDesc}内容如下：“${finalMsg}”`;
            queueTavernMessage(tavernMsg);
        }

    } catch (e) {
        console.error("❌ 提交评论失败:", e);
        alert("同步存档失败。");
    }
}
// 打开弹窗：区分评价与回复
function openCommentModal(targetId, replyUser = null, context = 'shop') {
    currentCommentContext = context;
    currentReplyTarget = replyUser;

    const overlay = document.getElementById("commentOverlay");
    const title = document.getElementById("commentTitle");
    const text = document.getElementById("commentText");
    const starArea = document.getElementById("star-selector-area");

    if (context === 'create-post') {
        // --- 发新帖模式 ---
        starArea.style.display = "none";
        title.innerText = "发布新帖子";
        text.placeholder = "分享你的奶茶新鲜事...";
    } else if (context === 'forum') {
        // --- 论坛回帖模式 ---
        starArea.style.display = "none";
        title.innerText = replyUser ? `回复 @${replyUser}` : `发表回帖`;
        text.placeholder = replyUser ? `回复 ${replyUser}...` : "说点什么吧...";
