// --- [1] 旧版码生成逻辑 (包含所有位移、缩放信息) ---
function generateV1Code() {
    if (editorState.layers.length === 0) return "";
    const masterList = getMasterIngredientList(); // 现在这只是 ingredientsDB

    const rawStr = editorState.layers
        .map((l) => {
            // 【核心修改点】：不直接找 ID，而是找这个原料对应的“母库底图名称”
            // 比如“草莓奶”变体的 baseImageName 是 “经典_全层”
            // 我们去母库里找 “经典_全层” 的索引
            const itemInLibrary = getIngredientById(l.id);
            const lookupName = itemInLibrary.baseImageName || itemInLibrary.name;

            const dbIdx = masterList.findIndex((db) => db.name === lookupName);

            if (dbIdx === -1) {
                console.warn("无法在母库中定位底图索引:", lookupName);
                return null;
            }

            const tint = l.tintColor ? l.tintColor.replace("#", "") : "";
            return [
                dbIdx,
                Math.round(l.x),
                Math.round(l.y),
                l.zIndex,
                Math.round(l.scale * 100),
                l.opacity,
                l.brightness,
                l.contrast,
                tint,
            ].join(",");
        })
        .filter(Boolean)
        .join(";");

    return btoa(rawStr); 
}
// --- [2] 新版码生成逻辑 (仅包含原料和染色) ---
function generateV2Code() {
    if (editorState.layers.length === 0) return "";
    const masterList = getMasterIngredientList();

    let parts = ["v2"];
    editorState.layers.forEach((l) => {
        // v2 逻辑下不记录墙体，解析时会自动补全
        if (l.id === 'wall_front' || l.id === 'wall_back') return;

        const dbIdx = masterList.findIndex((db) => db.id === l.id);
        if (dbIdx === -1) return;

        const tint = l.tintColor ? l.tintColor.replace("#", "") : "";
        parts.push(`${dbIdx},${tint}`);
    });

    return parts.join("|"); // 返回 v2|索引,颜色|索引,颜色...
}

// --- [3] 统一的复制处理函数 ---
async function copyRecipe(version) {
    const code = (version === 'v2') ? generateV2Code() : generateV1Code();
    const label = (version === 'v2') ? "新版极简码" : "旧版完整码";

    if (!code) {
        alert("画布是空的哦！");
        return;
    }

    try {
        await navigator.clipboard.writeText(code);
        showSysAlert(`✅ ${label} 已复制到剪贴板！\n\n内容：${code.substring(0, 30)}...`);
    } catch (err) {
        // 兜底方案
        prompt(`复制${label}:`, code);
    }
}

