            <div id="media-grid-${post.id}" style="display: grid; gap: 8px; 
                 grid-template-columns: ${post.media.length === 1 ? '1fr' : '1fr 1fr'}; margin-top: 10px;">
            </div>

            <div class="review-footer-actions" style="margin-top:20px; border-bottom: 1px solid #f5f5f5; padding-bottom:15px;">
                <div class="review-action-btn"><i class="fa-regular fa-thumbs-up"></i> <span class="action-count">${post.likes}</span></div>
                <div class="review-action-btn" onclick="event.stopPropagation(); openCommentModal('${post.id}', null, 'forum')">
                    <i class="fa-regular fa-comment"></i> <span class="action-count">${post.replies.length}</span>
                </div>
                <div class="review-action-btn"><i class="fa-solid fa-share"></i></div>
            </div>

            <div class="forum-inline-replies" style="margin-top: 15px; background: #f8f8f8; border-radius: 15px; padding: 15px;">
                ${post.replies.length > 0 ? post.replies.slice(0,2).map(r => `
                    <div style="font-size: 20px; margin-bottom: 8px; line-height: 1.4; cursor:pointer;" 
                         onclick="event.stopPropagation(); openCommentModal('${post.id}', '${r.user}', 'forum')">
                        <b style="color: #ff6b81;">${r.user}:</b> ${formatCommentText(r.text)}
                    </div>
                `).join("") : '<div style="color: #ccc; font-size: 18px;">点击查看更多评论...</div>'}
            </div>
        `;
