        post.media.forEach((item) => {
            const itemWrap = document.createElement("div");
            itemWrap.style.cssText = "width: 100%; aspect-ratio: 1/1; background: #eee; border-radius: 12px; overflow: hidden; position: relative;";
            grid.appendChild(itemWrap);
            if (item.type === "image") {
                itemWrap.innerHTML = `<img src="${item.data}" style="width:100%; height:100%; object-fit:cover;">`;
            } else if (item.type === "recipe") {
                let code = shopMenu[item.data] ? shopMenu[item.data].code : item.data;
