    const spacer = document.createElement("div");
    spacer.style.height = "120px";
    container.appendChild(spacer);
}
function renderPostMedia(containerId, post) {
    const container = document.getElementById(containerId);
    if (!container) return;

    if (post.type === "image") {
        const img = document.createElement("img");
        img.src = post.data;
        img.style.cssText = "width:100%; max-height:500px; object-fit:cover;";
        container.appendChild(img);
    } else if (post.type === "recipe") {
        // 处理配方展示逻辑
        let recipeCode = post.data;
        // 如果是玩家店铺里的奶茶名字，去 shopMenu 找 code
        if (shopMenu[post.data]) {
            recipeCode = shopMenu[post.data].code;
            container.innerHTML = `<div class="recipe-style-tag" style="position:absolute; top:10px; left:10px; z-index:10; background:#ff6b81; color:white;">店长认证配方</div>`;
