        container.appendChild(canvas);

        // 渲染配方预览 (复用之前的缩略图引擎)
        setTimeout(() => {
            const scale = canvas.clientWidth / 650;
            renderThumbnailFromCode(canvas, recipeCode, scale, false);
        }, 50);
    }
}

