// 格式化评论文字，让 @某某 变色
function formatCommentText(text) {
    if (!text) return "";
    return text.replace(/(@[^\s]+)/g, function(match) {
        return '<span style="color:#576b95; font-weight:bold; cursor:pointer;">' + match + '</span>';
    });
}


function parseMarkdown(text) {
    if (!text) return "";


    let step1 = text.replace(/“([^”]+)”/g, function(match, p1) {
        return '<strong style="color:#8b4513; font-weight:450;">“' + p1 + '”</strong>';
    });

    // 处理段落
    let paragraphs = step1.trim().split(/\n\s*\n/);
    return paragraphs.map(function(p) {
        let content = p.replace(/\n/g, '<br>');
        return '<p style="margin-bottom:25px;">' + content + '</p>';
    }).join('');
}

