async function handleMoriCommand(command) {
    console.log("🤖 Mori 动态指令执行:", command);

    try {
        await waitGlobalInitialized("Mvu");
        const mvuData = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        let feedback = "";

        // --- 1. 动态解锁指令：UNLOCK_X (如 UNLOCK_20) ---
        if (command.startsWith("UNLOCK_")) {
            const count = parseInt(command.split('_')[1]) || 5; // 提取下划线后的数字
            const allInDB = ingredientsDB.filter(i => !i.isFixed);
            const lockedOnes = allInDB.filter(i => !unlockedIngredients[i.id]);

            // 随机洗牌并提取请求的数量
            const toUnlock = lockedOnes.sort(() => 0.5 - Math.random()).slice(0, count);

            toUnlock.forEach(item => {
                unlockedIngredients[item.id] = { 
                    ...item, 
                    cost: item.cost || 5, 
                    season: "全" 
                };
            });
            feedback = `打通进货渠道，成功解锁了 ${toUnlock.length} 个新原料。`;
        }

        // --- 2. 动态资金指令：ADD_CASH_X (自带财务记账) ---
        else if (command.startsWith("ADD_CASH_")) {
            const amount = parseInt(command.split('_')[2]);

            // A. 修改余额
            shopFinancials.currentBalance += amount;

            // B. 自动记账：写入财务流水 (Record)
            const now = new Date();
            const dateStr = `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}`;

            shopFinancials.records.unshift({
                date: dateStr,
                item: "未知大额资金流入", // 账单里显示的明细
                amount: amount,
                type: "income"
            });

            syncGlobalBalance(); // 刷新顶栏和账单页UI
            feedback = `💰 拦截到系统溢出资金 ¥${amount}，已记入财务报表流水。`;
        }

        // --- 3. 动态品质提升：EVOLVE_QUALITY+X (如 EVOLVE_QUALITY+3) ---
        else if (command.startsWith("EVOLVE_QUALITY")) {
            let increment = 1;
            if (command.includes("+")) {
                increment = parseInt(command.split("+")[1]) || 1;
            }

            Object.values(unlockedIngredients).forEach(ing => {
                if (ing.coreTags) ing.coreTags.l = Math.min(5, (ing.coreTags.l || 1) + increment);
                if (ing.subTags) ing.subTags.l = Math.min(5, (ing.subTags.l || 1) + increment);
            });
            feedback = `✨ 优化了原料的底层属性，库中所有原料品质统一提升 ${increment} 星。`;
        }

        // 保存到云端存档
        await saveShopDataToMvu();

        // 弹出反馈
        if (feedback) {
            setTimeout(() => showSysAlert("🤖 AI 指令处理完毕：\n" + feedback), 800);
        }

    } catch (e) {
        console.error("Mori 执行失败:", e);
    }
}

