/**
 * 核心逻辑：适配旧版混合索引编码
 * 规则：旧版 code 索引 < 60 为母库 ingredientsDB， >= 60 为解锁库映射
 */
 async function convertOldVersionCodes() {
    if (!confirm("【数据修复】此操作将尝试转换旧版混合索引配方：\n1. 索引 0-59 映射至母库\n2. 索引 60+ 映射至当前解锁库\n\n转换后将自动同步至云端，是否继续？")) return;

    const masterList = ingredientsDB; 
    // 将当前的解锁对象转为数组，以模拟旧版的“解锁顺序索引”
    const unlockedList = Object.values(unlockedIngredients); 
    let fixCount = 0;

    for (let key in shopMenu) {
        let item = shopMenu[key];
        // 跳过空代码或已经是新版 v2 格式的代码
        if (!item.code || item.code.startsWith("v2|")) continue;

        try {
            const rawStr = atob(item.code);
            const layerRows = rawStr.split(";");
            let newRows = [];

            for (let row of layerRows) {
                if (!row) continue;
                let v = row.split(",");
                let oldIdx = parseInt(v[0]);
                let targetIngredient = null;

                // --- 核心转换逻辑 ---
                if (oldIdx < 60) {
                    // 情况 A: 属于母库前 60 位
                    targetIngredient = masterList[oldIdx];
                } else {
                    // 情况 B: 属于旧版偏移索引
                    targetIngredient = unlockedList[oldIdx - 60];
                }

                if (targetIngredient) {
                    // 在现在的 masterList 中寻找最新的物理索引
                    // 因为新版代码要求 code 必须基于全量 masterList 索引
                    const newIdx = masterList.findIndex(db => db.name === (targetIngredient.baseImageName || targetIngredient.name));

                    if (newIdx !== -1) {
                        v[0] = newIdx; // 更新索引位
                        newRows.push(v.join(","));
                    } else {
                        console.warn(`无法适配原料: ${targetIngredient.name}，索引: ${oldIdx}`);
                        newRows.push(row); // 找不着就不动，防止数据丢失
                    }
                } else {
                    newRows.push(row);
                }
            }

            if (newRows.length > 0) {
                const newCode = btoa(newRows.join(";"));
                if (item.code !== newCode) {
                    item.code = newCode;
                    fixCount++;
                }
            }
        } catch (e) {
            console.error(`配方 [${key}] 解析失败，可能已损坏:`, e);
        }
    }

    if (fixCount > 0) {
        // 1. 同步到 MVU
        await saveShopDataToMvu();
        // 2. 刷新 UI
        refreshRecipeList();
        showSysAlert(`✅ 适配完成！\n共修复了 ${fixCount} 个配方的索引。数据已同步至云端。`);
    } else {
        showSysAlert("未检测到需要修复的旧版索引配方。");
    }
}
