    likes: z.coerce.number().default(0),
    replies: z.array(ForumReplySchema).default([])
}).passthrough();


// =============================
// 2. 系统子结构
// =============================

const ShopConfigSchema = z.object({
    identity: z.object({
        name: z.string().default('微风茶舍'),
        level: z.coerce.number().default(1),
        xp: z.coerce.number().default(0),
        xpNext: z.coerce.number().default(100),
        reputation: z.string().default('默默无闻'),
        address: z.string().default('未知'),
        establishedDate: z.string().default('')
    }).default({}),
    stats: z.object({
        popularity: z.coerce.number().default(10),
        hygiene: z.coerce.number().default(80),
        service: z.coerce.number().default(80),
        seatingCapacity: z.coerce.number().default(4),
        staffCount: z.coerce.number().default(1),
        dailyRent: z.coerce.number().default(50),
        avgWaitTime: z.string().default('10min')
    }).default({}),

    activeEffects: z.array(z.any()).default([]),
    buffMarket: z.array(z.any()).default([])
}).passthrough().default({});

const ShopFinancialsSchema = z.object({
    currentBalance: z.coerce.number().default(500),
    totalIncome: z.coerce.number().default(0),
    totalExpense: z.coerce.number().default(0),
    lastUpdate: z.string().default(''),
    records: z.array(z.any()).default([])
}).passthrough().default({});

const PhoneChatSchema = z.object({
    id: z.string(),
    name: z.string(),
    history: z.array(z.any()).default([])
}).passthrough();

const MatchResultSchema = z.object({
    competitors: z.array(z.any()).default([]),
    judges: z.array(z.any()).default([]),
    result: z.object({ winner: z.string().default(''), prize: z.string().default('') }).passthrough().default({})
}).passthrough().default({});

const CompetitorShopSchema = z.object({
    positioning: z.string().default('未知'),
    avgPrice: z.coerce.number().default(0),
    rating: z.coerce.number().default(3.0),
    desc: z.string().default('一家神秘的店铺。'),
    flagship: z.object({ name: z.string().default(''), price: z.number().optional(), code: z.any().nullable().optional()}).passthrough().default({}),
    reviews: z.array(z.any()).default([])
}).passthrough();

// =============================
// 系统设置与场景状态子结构
// =============================

const AppSettingsSchema = z.object({
    drinkBackground: z.string().nullable().default(null),
    // 升级为数组：存储待处理场景队列
    pendingScenes: z.array(z.string()).default([]), 
}).passthrough().default({});



// =============================
// 3. 最终统一 Schema (核心修复)
// =============================

export const Schema = z.object({
    // 使用 .object({}).catchall() 确保这些“篮子”可以被 add 新键
    unlockedIngredients: z.object({}).catchall(IngredientSchema).default({}),
    shopMenu: z.object({}).catchall(DrinkRecipeSchema).default({}),
shopMenuAI: z.object({}).catchall(z.any()).default({}),    
    customersDB: z.object({}).catchall(CustomerSchema).default({}),

    tempDrinkStats: DrinkRecipeSchema.default({}),
    unlockedIngredientListStr: z.string().default(''),
  // 建议放在你的 MVU 变量定义区域
shopRankingListStr: z.string().default(''),
    shopConfig: ShopConfigSchema,
    shopFinancials: ShopFinancialsSchema,
        appSettings: AppSettingsSchema, 
    phoneChatDB: z.object({}).catchall(PhoneChatSchema).default({}),
    phoneTaskDB: z.object({}).catchall(z.any()).default({}),
    phoneMatchDB: z.object({}).catchall(z.any()).default({}),
    matchResultsDB: z.object({}).catchall(MatchResultSchema).default({}),
    phoneShopDB: z.object({}).catchall(CompetitorShopSchema).default({}),
      phoneForumDB: z.object({}).catchall(ForumPostSchema).default({}),
    worldConfig: z.object({
        year: z.string().default("2026年"),
        season: z.string().default("春天"),
        time: z.string().default("白天"),
        weather: z.string().default("晴天")
    }).default({})
}).passthrough(); // 允许根部扩展

// 注册
;(() => {
    registerMvuSchema(Schema);
})();

$(() => {
  // 移除除了最后一楼以外的楼层
  $('#chat > .mes').not('.last_mes').remove();

  // 当聊天文件变更时, 重新加载前端界面或脚本
  let current_chat_id = SillyTavern.getCurrentChatId();
  eventOn(tavern_events.CHAT_CHANGED, chat_id => {
    if (current_chat_id !== chat_id) {
      current_chat_id = chat_id;
      reloadIframe();
    }
  })
})
